import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from sklearn.preprocessing import StandardScaler

MAX_DRIVERS = 4

def design(feats):
    # Filter to only include features with significant effect sizes
    effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('expression', 'copy_number', 'clinical'):
            # Use Welch's t-test p-value as proxy for effect size significance
            t_stat = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i], equal_var=False)[0]
            p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i], equal_var=False)[1]
            if p_val < 0.05:
                effects.append((fid, abs(t_stat)))

    # Sort by effect size
    effects.sort(key=lambda x: x[1], reverse=True)

    # Select top candidates
    candidates = [fid for fid, _ in effects[:10]]

    # Check for product terms among correlated pairs
    correlated_pairs = [
        ('DUT9', 'MFT1A'), ('MFT1A', 'IQOM18A'), ('DUT9', 'IQOM18A'),
        ('QZX11', 'MFT1A'), ('QZX11', 'DUT9'), ('MFT1A', 'DHT9A'),
        ('IQOM18A', 'DHT9A'), ('QZX11', 'IQOM18A'), ('DUT9', 'DHT9A'),
        ('MFT1A', 'LMR4'), ('IQOM18A', 'LMR4'), ('QZX11', 'LMR4'),
        ('DHT9A', 'LMR4'), ('QZX11', 'DHT9A'), ('DHT9A', 'ENQ19'),
        ('DUT9', 'LMR4'), ('IQOM18A', 'WCQB8L'), ('FTMP7', 'HHP6')
    ]

    # Look for product terms among highly correlated pairs
    products = []
    for a, b in correlated_pairs:
        if a in candidates and b in candidates:
            # Check if both features are present
            idx_a = feats.column(a)
            idx_b = feats.column(b)
            if idx_a is not None and idx_b is not None:
                # Compute correlation
                corr = np.corrcoef(feats.x[:, idx_a], feats.x[:, idx_b])[0, 1]
                if abs(corr) >= 0.6:
                    products.append((a, b))

    # If we have product terms, select those two features as drivers
    if products:
        a, b = products[0]
        return Design(
            drivers=(a, b),
            columns=(a, b),
            products=(products[0],),
            loadings={a: 1.0, b: 1.0}
        )

    # Otherwise, use top features based on effect size
    if len(effects) > 0:
        top_features = [fid for fid, _ in effects[:MAX_DRIVERS]]
        return Design(
            drivers=tuple(top_features),
            columns=tuple(top_features),
            products=(),
            loadings={fid: 1.0 for fid in top_features}
        )

    # No mechanism case
    return Design(
        drivers=(),
        columns=(),
        products=(),
        loadings={}
    )

